<template>
  <div v-loading="loading" class="course-workspace" :data-role="teacher ? 'teacher' : 'student'">
    <el-button text class="back-link" @click="router.push(base)">← {{ teacher ? '返回我的授课' : '返回我的课程' }}</el-button>
    <template v-if="course">
      <header class="course-hero" :class="{ 'with-cover': course.coverUrl }"><img v-if="course.coverUrl" class="hero-image" :src="course.coverUrl" alt="课程封面" /><div class="hero-shade" /><div class="hero-copy"><div class="hero-labels"><span>{{ teacher ? '教学空间' : '学习空间' }}</span><el-tag :type="course.isFinished === 1 ? 'info' : 'success'">{{ course.isFinished === 1 ? '已结课' : '进行中' }}</el-tag></div><h1>{{ course.courseName }}</h1><p>课程号 {{ course.courseId }} <span>·</span> {{ course.fixedSchedule ? `每周${weekdays[course.classWeekday-1]} ${course.classTime}` : '授课时间灵活安排' }}</p><div class="hero-bottom"><div class="teacher-line"><el-avatar :size="32" :src="data.teacher?.avatar">{{ data.teacher?.name?.slice(0,1) }}</el-avatar><span>主讲教师 {{ data.teacher?.name }}</span></div><el-button v-if="teacher && course.isFinished !== 1" type="primary" @click="openClass">{{ activeSession ? '进入当前课堂' : '开始上课' }} <i class="ph ph-arrow-up-right" aria-hidden="true" /></el-button><el-button v-else-if="!teacher && activeSession?.mode === 'ONLINE'" type="primary" @click="router.push(`/student/live/${activeSession.sessionId}`)">进入直播间</el-button></div></div></header>
      <nav class="course-tabs" aria-label="课程页面"><RouterLink v-for="tab in tabs" :key="tab.id" :to="`${base}/${course.courseId}${tab.id === 'overview' ? '' : '/'+tab.id}`" :class="{ selected: section === tab.id }"><i :class="tab.icon" aria-hidden="true" />{{ tab.label }}<span v-if="tab.id === 'applications' && course.pendingApplications" class="tab-count">{{ course.pendingApplications }}</span></RouterLink></nav>

      <section v-if="section === 'overview'" class="overview-grid">
        <div class="overview-main"><div class="metric-grid"><div><span>班级成员</span><strong>{{ course.memberCount }}<small> 人</small></strong></div><div><span>{{ teacher ? '待审核申请' : '本课得分' }}</span><strong>{{ teacher ? course.pendingApplications : score(data.myScore) }}</strong></div><div><span>学习资料</span><strong>{{ data.materialCount }}<small> 份</small></strong></div></div>
          <section class="surface"><div class="section-heading"><h3>课程安排</h3><i class="ph ph-calendar-blank" aria-hidden="true" /></div><div class="detail-row"><span>授课时间</span><strong>{{ course.fixedSchedule ? `每周${weekdays[course.classWeekday-1]} ${course.classTime}` : '由教师灵活安排' }}</strong></div><div class="detail-row"><span>加入方式</span><strong>{{ course.approvalRequired ? '需要教师审核入课申请' : '通过课程号直接加入' }}</strong></div><div class="detail-row"><span>人数上限</span><strong>{{ course.maxStudents ? `${course.maxStudents} 人` : '不限制' }}</strong></div><div class="detail-row"><span>成员成绩</span><strong>{{ course.showStudentRanking ? '已开放成绩与排名' : '学生仅查看本人分数' }}</strong></div></section>
          <section v-if="teacher" class="surface course-management"><div class="section-heading"><h3>课程管理</h3><i class="ph ph-sliders-horizontal" aria-hidden="true" /></div><p>结课后学生可以给教师打分；已结课课程不占用进行中的课程名额。</p><div><el-button v-if="course.isFinished !== 1" type="warning" plain @click="finishCourseAction">结束课程</el-button><el-button v-else type="success" plain @click="restoreCourse">取消结课</el-button><el-button type="danger" text @click="deleteCourseAction">删除课程</el-button></div></section>
          <section v-else class="surface"><div class="section-heading"><h3>教师评价</h3><i class="ph ph-star" aria-hidden="true" /></div><div v-if="data.myTeacherScore != null" class="rating-result"><span>你给教师的评分</span><strong>{{ score(data.myTeacherScore) }}<small> / 10</small></strong></div><div v-else-if="course.isFinished === 1"><p>本课程已结课，可为教师打 1–10 分，提交后不可重复打分。</p><el-slider v-model="ratingScore" :min="1" :max="10" :step="0.5" show-stops /><el-button type="primary" :loading="rating" @click="rate">提交评分</el-button></div><el-alert v-else title="课程结课后才能给教师打分" type="info" :closable="false" /></section>
        </div>
        <aside class="overview-side"><section class="surface teacher-profile"><el-avatar :size="68" :src="data.teacher?.avatar">{{ data.teacher?.name?.slice(0,1) }}</el-avatar><h3>{{ data.teacher?.name }}</h3><span>主讲教师</span><p>{{ data.teacher?.signature || '一起完成本课程的学习与探索' }}</p></section><section class="surface shortcuts"><h3>课程入口</h3><button @click="go('members')"><i class="ph ph-users-three" aria-hidden="true" /><span>班级成员</span><i class="ph ph-caret-right" aria-hidden="true" /></button><button @click="go('materials')"><i class="ph ph-folder-open" aria-hidden="true" /><span>学习资料</span><i class="ph ph-caret-right" aria-hidden="true" /></button><button v-if="teacher" @click="go('applications')"><i class="ph ph-user-plus" aria-hidden="true" /><span>入课申请</span><span v-if="course.pendingApplications" class="tab-count">{{ course.pendingApplications }}</span></button><button v-else @click="go('summary')"><i class="ph ph-chart-bar" aria-hidden="true" /><span>个人总结</span><i class="ph ph-caret-right" aria-hidden="true" /></button></section></aside>
      </section>

      <section v-else-if="section === 'members'" class="surface members-page"><div class="section-heading"><div><h3>班级成员 <span class="muted">{{ members.length }} 人</span></h3><p>{{ course.showStudentRanking ? '按课程成绩排序' : '按加入课程的先后顺序展示' }}</p></div><div class="member-tools"><el-switch v-if="teacher" :model-value="course.showStudentRanking !== false" :loading="rankingSaving" active-text="允许学生查看排名" @change="toggleRanking" /><el-button text @click="loadMembers">刷新</el-button></div></div><el-alert v-if="!teacher && !course.showStudentRanking" title="教师未开放课程成绩排名，仅展示你的分数，其他同学分数不可见" type="info" :closable="false" /><el-table :data="members" empty-text="暂无班级成员"><el-table-column v-if="course.showStudentRanking" prop="rank" label="排名" width="80" /><el-table-column v-else type="index" label="序号" width="80" /><el-table-column label="成员" min-width="180"><template #default="{ row }"><div class="member-name"><el-avatar :src="row.avatar" :size="40">{{ row.nickname?.slice(0,1) }}</el-avatar><div><strong>{{ row.nickname || '学生' }}<el-tag v-if="String(row.studentId) === String(user.userId)" size="small">我</el-tag></strong><p>ID {{ row.studentId }}</p></div></div></template></el-table-column><el-table-column label="加入时间" min-width="145"><template #default="{ row }">{{ date(row.joinedAt) }}</template></el-table-column><el-table-column label="课程分数" width="110"><template #default="{ row }"><strong v-if="row.studentScore != null" class="member-score">{{ score(row.studentScore) }}</strong><span v-else class="muted">未开放</span></template></el-table-column><el-table-column v-if="teacher" label="操作" width="90"><template #default="{ row }"><el-button link type="danger" :disabled="course.isFinished === 1" @click="removeMember(row)">移除</el-button></template></el-table-column></el-table></section>

      <section v-else-if="section === 'materials'" class="surface materials-page"><div class="section-heading"><div><h3>课程资料</h3><p>学习文档与课件，支持 PDF、Word、PPT、Excel 等格式</p></div><el-upload v-if="teacher" :show-file-list="false" :auto-upload="false" :on-change="uploadMaterial" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.zip,.rar,.png,.jpg,.jpeg"><el-button type="primary" :loading="uploading"><i class="ph ph-upload-simple" aria-hidden="true" /> 上传资料</el-button></el-upload></div><el-empty v-if="!materials.length" description="教师还没有上传课程资料" /><article v-for="file in materials" :key="file.id" class="material-row"><div class="file-icon"><i :class="file.originalName.toLowerCase().endsWith('.pdf') ? 'ph ph-file-pdf' : 'ph ph-file-text'" aria-hidden="true" /></div><div class="material-info"><h4>{{ file.originalName }}</h4><p>{{ size(file.fileSize) }} · {{ date(file.uploadedAt) }}</p></div><el-button v-if="file.originalName.toLowerCase().endsWith('.pdf')" text type="primary" @click="download(file,true)">查看</el-button><el-button plain size="small" @click="download(file)">下载</el-button><el-button v-if="teacher" text type="danger" @click="removeMaterial(file)">删除</el-button></article><p v-if="teacher" class="hint">单个文件最大 10 MB；只有本课程成员可以下载资料。</p></section>

      <section v-else-if="section === 'applications' && teacher" class="surface"><div class="section-heading"><div><h3>入课申请</h3><p>仅处理当前课程的学生申请</p></div><el-button text @click="loadApplications">刷新</el-button></div><el-table :data="applications" empty-text="暂无待处理的入课申请"><el-table-column label="申请人" min-width="190"><template #default="{ row }"><div class="member-name"><el-avatar :src="row.avatar" :size="40">{{ row.nickname?.slice(0,1) }}</el-avatar><div><strong>{{ row.nickname }}</strong><p>ID {{ row.studentId }}</p></div></div></template></el-table-column><el-table-column label="申请时间" min-width="150"><template #default="{ row }">{{ date(row.appliedAt) }}</template></el-table-column><el-table-column label="操作" width="170"><template #default="{ row }"><el-button type="primary" link :disabled="reviewing" @click="review(row,true)">通过</el-button><el-button type="danger" link :disabled="reviewing" @click="review(row,false)">拒绝</el-button></template></el-table-column></el-table></section>

      <section v-else-if="section === 'settings' && teacher" class="surface settings-page"><div class="section-heading"><div><h3>课程设置</h3><p>修改封面、授课时间、入课要求及人数上限</p></div></div><CourseSettingsEditor :course="course" :member-count="Number(course.memberCount)" @saved="settingsSaved" /></section>

      <section v-else-if="section === 'summary' && !teacher" class="summary-page"><div class="surface"><div class="section-heading"><div><h3>个人学习总结</h3><p>你的课堂参与、作答与课程成绩</p></div><el-button text @click="loadSummary">刷新</el-button></div><div class="summary-score"><div><span>本课当前分数</span><strong>{{ score(summary.score) }}</strong></div><i class="ph ph-chart-line-up" aria-hidden="true" /></div><div class="summary-metrics"><article v-for="item in summaryMetrics" :key="item.key"><i :class="item.icon" aria-hidden="true" /><h4>{{ item.label }}</h4><strong>{{ summary[item.key] || 0 }}<small> / {{ summary[item.total] || 0 }}</small></strong><el-progress :percentage="summary[item.total] ? Math.round(100*summary[item.key]/summary[item.total]) : 0" :stroke-width="6" :show-text="false" /></article></div><p class="hint">考试次数按已提交的答卷统计；小测计入参与次数，作业按完成次数统计。</p></div></section>
    </template>
    <el-empty v-else-if="!loading" description="课程不存在或暂不可访问" />
    <el-dialog v-model="classVisible" title="选择授课方式" width="min(480px,94vw)" align-center><div class="class-choices"><button @click="enterClass('ONLINE')"><i class="ph ph-video-camera" aria-hidden="true" /><strong>网络授课</strong><span>摄像头、屏幕共享与麦克风直播</span></button><button @click="enterClass('LOCAL')"><i class="ph ph-chalkboard-teacher" aria-hidden="true" /><strong>本地授课</strong><span>签到、随机点名与课堂小测</span></button></div></el-dialog>
  </div>
</template>
<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useUserStore} from '@/stores/user'
import {useUnreadStore} from '@/stores/unread'
import {fetchCourseMembers,removeStudent,finishCourse,unfinishCourse,deleteCourse} from '@/api/course'
import {activeClass,reviewApplication} from '@/api/classroom'
import {courseOverview,setCourseRanking,courseApplications,courseSummary,courseMaterials,uploadCourseMaterial,deleteCourseMaterial,downloadCourseMaterial} from '@/api/courseWorkspace'
import {rateTeacher} from '@/api/teacherEvaluation'
import CourseSettingsEditor from '@/components/CourseSettingsEditor.vue'
import {onChatEvent} from '@/utils/websocket'
const route=useRoute(),router=useRouter(),user=useUserStore(),unread=useUnreadStore(),teacher=computed(()=>user.role==='TEACHER'),base=computed(()=>teacher.value?'/teacher/courses':'/student/courses')
const id=computed(()=>route.params.courseId),section=computed(()=>route.params.section||'overview'),data=ref({}),course=computed(()=>data.value.course),loading=ref(false),members=ref([]),materials=ref([]),applications=ref([]),summary=ref({}),rankingSaving=ref(false),uploading=ref(false),reviewing=ref(false),rating=ref(false),ratingScore=ref(8),classVisible=ref(false),activeSession=ref(null)
const weekdays=['一','二','三','四','五','六','日']
const tabs=computed(()=>[{id:'overview',label:'课程概览',icon:'ph ph-squares-four'},{id:'members',label:'班级成员',icon:'ph ph-users-three'},{id:'materials',label:'资料',icon:'ph ph-folder-open'},...(teacher.value?[{id:'applications',label:'入课申请',icon:'ph ph-user-plus'},{id:'settings',label:'课程设置',icon:'ph ph-sliders-horizontal'}]:[{id:'summary',label:'个人总结',icon:'ph ph-chart-bar'}])])
const summaryMetrics=[{key:'quizCount',total:'quizTotal',label:'小测次数',icon:'ph ph-exam'},{key:'checkInCount',total:'checkInTotal',label:'签到次数',icon:'ph ph-calendar-check'},{key:'examCount',total:'examTotal',label:'考试次数',icon:'ph ph-pencil-line'},{key:'homeworkCount',total:'homeworkTotal',label:'作业完成次数',icon:'ph ph-notebook'}]
let timer
const off=onChatEvent(event=>{if(event.type==='COURSE_SETTINGS_UPDATED'&&String(event.data?.courseId)===String(id.value))load()})
const score=v=>v==null?'-':Number(v).toFixed(1),date=v=>v?String(v).replace('T',' ').slice(0,16):'-',size=v=>Number(v)>1024*1024?(Number(v)/1024/1024).toFixed(1)+' MB':Math.max(1,Math.ceil(Number(v)/1024))+' KB'
function go(tab){router.push(`${base.value}/${id.value}/${tab}`)}
async function load(){loading.value=true;const current=id.value;try{const r=await courseOverview(current);if(String(current)!==String(id.value))return;data.value=r.data;activeSession.value=(await activeClass(current)).data;await loadSection()}catch{}finally{loading.value=false}}
async function loadMembers(){try{members.value=(await fetchCourseMembers(id.value)).data||[]}catch{}}
async function loadMaterials(){try{materials.value=(await courseMaterials(id.value)).data||[]}catch{}}
async function loadApplications(){if(!teacher.value)return;try{applications.value=(await courseApplications(id.value)).data||[];if(course.value)course.value.pendingApplications=applications.value.length}catch{}}
async function loadSummary(){try{summary.value=(await courseSummary(id.value)).data||{}}catch{}}
async function loadSection(){if(!tabs.value.some(t=>t.id===section.value)){router.replace(`${base.value}/${id.value}`);return}if(section.value==='members')await loadMembers();else if(section.value==='materials')await loadMaterials();else if(section.value==='applications')await loadApplications();else if(section.value==='summary')await loadSummary()}
async function toggleRanking(value){rankingSaving.value=true;try{await setCourseRanking(id.value,value);course.value.showStudentRanking=value;await loadMembers();ElMessage.success('学生成绩可见性已更新')}catch{}finally{rankingSaving.value=false}}
async function removeMember(row){try{await ElMessageBox.confirm(`确认将 ${row.nickname||row.studentId} 移出本课程？`,'移除成员');await removeStudent(id.value,row.studentId);await load();await loadMembers()}catch{}}
async function review(row,approve){reviewing.value=true;try{await reviewApplication(id.value,row.studentId,approve);ElMessage.success(approve?'已通过入课申请':'已拒绝申请');await loadApplications();await load();unread.refresh()}catch{}finally{reviewing.value=false}}
async function uploadMaterial(item){if(!item.raw)return;if(item.raw.size>10*1024*1024){ElMessage.warning('单个文件不能超过10 MB');return}uploading.value=true;try{await uploadCourseMaterial(id.value,item.raw);await loadMaterials();data.value.materialCount=materials.value.length;ElMessage.success('课程资料已上传')}catch{}finally{uploading.value=false}}
async function removeMaterial(file){try{await ElMessageBox.confirm(`删除资料「${file.originalName}」？`,'删除资料');await deleteCourseMaterial(id.value,file.id);await loadMaterials();data.value.materialCount=materials.value.length;ElMessage.success('资料已删除')}catch{}}
async function download(file,preview=false){try{const blob=await downloadCourseMaterial(id.value,file.id);const url=URL.createObjectURL(preview?new Blob([blob],{type:'application/pdf'}):blob);if(preview)window.open(url,'_blank','noopener');else{const a=document.createElement('a');a.href=url;a.download=file.originalName;a.click()}setTimeout(()=>URL.revokeObjectURL(url),60000)}catch{}}
async function settingsSaved(){await load();go('overview')}
async function openClass(){try{const r=await activeClass(id.value);if(r.data){router.push(`/teacher/classroom/${id.value}?session=${r.data.sessionId}`);return}classVisible.value=true}catch{}}
function enterClass(mode){classVisible.value=false;router.push(`/teacher/classroom/${id.value}?mode=${mode}`)}
async function finishCourseAction(){try{await ElMessageBox.confirm(`确认结束「${course.value.courseName}」？`,'结束课程',{type:'warning'});await finishCourse(id.value);await load();ElMessage.success('课程已结课')}catch{}}
async function restoreCourse(){try{await unfinishCourse(id.value);await load();ElMessage.success('课程已恢复')}catch{}}
async function deleteCourseAction(){try{await ElMessageBox.confirm('将删除课程、相关记录和课程资料，确认继续？','删除课程',{type:'error',confirmButtonText:'确认删除'});await deleteCourse(id.value);unread.refresh();router.replace(base.value)}catch{}}
async function rate(){rating.value=true;try{await rateTeacher({courseId:Number(id.value),teacherId:course.value.teacherId,score:ratingScore.value});await load();ElMessage.success('评分已提交')}catch{}finally{rating.value=false}}
watch(section,()=>{if(course.value)loadSection()});watch(id,()=>{data.value={};load()})
onMounted(()=>{load();timer=setInterval(()=>{if(teacher.value&&course.value)loadApplications();if(!teacher.value&&section.value==='members')loadMembers();if(!teacher.value&&section.value==='summary')loadSummary()},10000)})
onUnmounted(()=>{clearInterval(timer);off()})
</script>
<style scoped>
.back-link { margin-bottom:14px; }.course-hero { position:relative;min-height:270px;background:linear-gradient(115deg,#183a60,#287e9d 65%,#55aaa6);border-radius:22px;overflow:hidden;color:white; }.course-workspace[data-role=student] .course-hero { background:linear-gradient(115deg,#194e66,#238d9b 65%,#65c6b1); }.hero-image,.hero-shade { position:absolute;inset:0;width:100%;height:100%;object-fit:cover; }.hero-shade { background:linear-gradient(90deg,#102638cc,#10263845); }.hero-copy { position:relative;padding:30px 34px; }.hero-labels { display:flex;align-items:center;gap:14px; }.hero-labels > span { font-size:11px;letter-spacing:.2em;color:#d0eafa; }.hero-copy h1 { margin:23px 0 13px;font-size:32px;line-height:1.3; }.hero-copy p { font-size:13px;color:#e1f0f6; }.hero-copy p > span { margin:0 10px; }.hero-bottom,.teacher-line { display:flex;align-items:center;gap:12px; }.hero-bottom { justify-content:space-between;margin-top:26px; }.teacher-line { font-size:13px; }.hero-bottom .el-button { gap:8px; }.course-tabs { display:flex;gap:8px;padding:14px;background:white;border:1px solid #edf1f6;border-radius:15px;margin:24px 0;overflow-x:auto; }.course-tabs a { display:flex;gap:9px;align-items:center;padding:11px 17px;border-radius:10px;color:#6c7c90;font-size:14px;white-space:nowrap; }.course-tabs a.selected { background:#edf8ff;color:#199bcf; }.tab-count { display:inline-flex;align-items:center;justify-content:center;min-width:19px;height:19px;border-radius:20px;background:#ef4a62;color:white;font-size:11px;padding:0 5px; }.overview-grid { display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:22px; }.overview-main,.overview-side { display:grid;gap:22px;align-content:start; }.surface { background:white;border:1px solid #edf1f6;border-radius:18px;padding:26px; }.metric-grid { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px; }.metric-grid > div { padding:22px;background:white;border:1px solid #edf1f6;border-radius:16px; }.metric-grid span { display:block;font-size:12px;color:#8e9aad;margin-bottom:12px; }.metric-grid strong { font-size:28px;color:#27394f; }.metric-grid small { font-size:12px;font-weight:400;color:#93a0b0; }.section-heading { display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:22px; }.section-heading h3,h3 { margin:0;font-size:18px; }.section-heading > i { font-size:24px;color:#b1d6e3; }.section-heading p,.surface > p,.hint { font-size:13px;color:#8e9aad;line-height:1.8; }.detail-row { display:flex;justify-content:space-between;gap:20px;padding:16px 0;border-bottom:1px solid #f0f3f7;font-size:13px; }.detail-row:last-child { border:0; }.detail-row > span { color:#8c99a9; }.detail-row strong { font-weight:500;color:#485c75; }.teacher-profile { text-align:center; }.teacher-profile h3 { margin:14px 0 7px; }.teacher-profile > span { font-size:12px;color:#8c99a9; }.teacher-profile p { font-size:13px;line-height:1.9;color:#98a2b1;margin-top:18px; }.shortcuts h3 { margin-bottom:20px; }.shortcuts button { display:flex;align-items:center;gap:12px;width:100%;padding:16px 0;border:0;border-bottom:1px solid #f1f4f8;background:white;color:#6d7d91;text-align:left;cursor:pointer; }.shortcuts button span:nth-child(2) { flex:1; }.shortcuts button > i { font-size:21px; }.course-management > div:last-child { margin-top:20px; }.rating-result { display:flex;align-items:center;justify-content:space-between;padding:12px 0;color:#8996a7;font-size:13px; }.rating-result strong { font-size:30px;color:#13a0ca; }.rating-result small { font-size:13px;color:#9aa5b4; }.member-tools { display:flex;align-items:center;gap:20px;flex-wrap:wrap; }.member-name { display:flex;align-items:center;gap:13px;padding:8px 0; }.member-name strong { font-size:14px;font-weight:500;display:flex;align-items:center;gap:8px; }.member-name p { color:#9aa5b4;font-size:11px;margin:6px 0 0; }.muted { color:#a4adba;font-size:12px;font-weight:400; }.member-score { color:#2199c7;font-weight:600; }.members-page .el-alert { 